// Tra cứu theo tình huống, không gieo — hướng 3 của cẩm nang (bản đồ NGHIEN-CUU/00-ban-do-kho-sach.md mục 12). Trang "th".
// que[]: quẻ (n 1–64) hợp tượng nhất, kèm hao (1–6) khi một hào nói đúng tình huống. trich: một câu Hán chép đúng lời quẻ (tu) hoặc hào từ (hao)
// trong data/nguyen-van.js (Wikisource 周易, phạm vi công cộng); tool tools/kiem-tra-cam-nang-2.mjs dò lại trong nguon/zh/NN.txt. hv: một âm tiết một chữ Hán.
// ten, viSao, dich, ungXu, canhBao: BẢN BIÊN SOẠN CỦA KHO (25/10/2026), soi lời quẻ vào tình thế đời nay; KHÔNG phải lời người xưa.
// viSao tóm tượng quẻ, Thoán, Đại tượng bằng lời của kho, không chép nguyên bản dịch. canhBao.ma: mã tình huống kế tiếp khi tình thế đổi.
window.KD_TINH_HUONG = {
moDau: "Đây là cách người xưa dùng Dịch làm sách tham mưu: tìm tình thế giống mình rồi đọc lời khuyên, không cần gieo. Hệ từ gọi là xem tượng mà ngẫm lời. Dưới đây là 59 tình huống thường gặp, gom tám nhóm. Mỗi tình huống chỉ một hai quẻ hợp tượng nhất, một câu Hán gốc, vài việc nên làm và nên tránh. Cuối mỗi mục có lời cảnh báo: khi tình thế đổi thì đọc mục nào tiếp.",
nhom: [
 {ma: "ks", ten: "Khởi sự"}, {ma: "ct", ten: "Chờ thời"}, {ma: "ht", ten: "Hợp tác và quan hệ"}, {ma: "tc", ten: "Tranh chấp và khó khăn"},
 {ma: "tb", ten: "Tiền bạc"}, {ma: "gi", ten: "Gia đình"}, {ma: "ld", ten: "Lãnh đạo và tổ chức"}, {ma: "lk", ten: "Lui, kết thúc, mất mát"}],
th: [
// ===== Khởi sự =====
{ma: "ks1", nhom: "ks", ten: "Muốn bắt đầu việc lớn mà chưa đủ lực", que: [{n: 1, hao: 1}, {n: 26}],
 viSao: "Quẻ Càn sáu hào đều dương, là sức mạnh thuần. Nhưng hào đầu nằm dưới cùng: rồng còn ẩn, chưa ai thấy. Thoán nói sáu ngôi thành theo thời. Có sức mà chưa đến lúc thì chưa dùng. Quẻ Đại Súc (trời trong núi) dạy chứa sức trước khi tung ra.",
 trich: {n: 1, hao: 1, zh: "潛龍勿用", hv: "Tiềm long vật dụng.", dich: "Rồng còn ẩn dưới nước, chưa phải lúc dùng."},
 ungXu: {nen: ["Tích ba thứ trước: tiền đủ sống một năm, một kỹ năng làm thật tốt, hai người tin mình.", "Làm thử nhỏ, tối và cuối tuần, chưa cần ai biết.", "Ghi vào sổ mỗi lần thấy nhu cầu thật của người sẽ dùng việc mình làm."],
  tranh: ["Nghỉ việc, vay tiền lớn, công bố rầm rộ khi chưa có gì chạy.", "So mình với người đã làm mười năm."]},
 canhBao: {y: "Khi đã có kết quả đầu và người tin mình, việc sang bước lộ ra; đọc", ma: "ks5"}},
{ma: "ks2", nhom: "ks", ten: "Mới khởi nghiệp, cái gì cũng thiếu, cái gì cũng rối", que: [{n: 3, hao: 1}],
 viSao: "Quẻ Truân là sấm dưới mây: muốn động mà trên còn mờ. Tượng là cỏ non đội đất mà lên, khó buổi đầu. Thoán nói đầy khó mà vẫn thông. Đại tượng dạy gỡ từng sợi như xe tơ. Hào đầu bảo quanh quẩn chưa đi được thì giữ vững và tìm người giúp.",
 trich: {n: 3, hao: 1, zh: "磐桓，利居貞，利建侯", hv: "Bàn hoàn, lợi cư trinh, lợi kiến hầu.", dich: "Còn quanh quẩn chưa đi được; nên ở yên giữ vững, nên gây dựng người giúp mình."},
 ungXu: {nen: ["Chọn một việc cốt lõi làm cho chạy, các việc khác để sau.", "Tìm một người làm cùng gánh được phần mình yếu.", "Đặt nếp làm việc đều: giờ nào việc nào, sổ sách ghi ngay ngày đầu.", "Chấp nhận chậm; buổi đầu chậm là thường."],
  tranh: ["Mở nhiều mặt hàng, nhiều chi nhánh khi chưa có gì bán được đều."]},
 canhBao: {y: "Nếu hơn một năm vẫn rối, tiền hụt dần mà không rõ vì sao, đó không còn là khó buổi đầu; đọc", ma: "tc3"}},
{ma: "ks3", nhom: "ks", ten: "Chưa biết nghề, phải học, cần tìm thầy", que: [{n: 4}],
 viSao: "Quẻ Mông là suối chảy dưới núi: nước mới ra, chưa biết đường. Tượng là người non dại cần được khai sáng. Lời quẻ nói kẻ học phải tự tìm thầy; hỏi lần đầu được bảo, hỏi đi hỏi lại thành nhờn. Đại tượng dạy làm quả quyết, nuôi đức từ việc nhỏ.",
 trich: {n: 4, zh: "匪我求童蒙，童蒙求我", hv: "Phỉ ngã cầu đồng mông, đồng mông cầu ngã.", dich: "Không phải thầy đi tìm người học; người học phải tìm đến thầy."},
 ungXu: {nen: ["Tự tìm một người giỏi nghề, xin học thật, trả công sòng phẳng.", "Hỏi một lần, làm ngay, rồi mới hỏi tiếp; không hỏi thay cho làm.", "Nhận việc nhỏ người ta giao, làm xong không để ai sửa lại."],
  tranh: ["Học ba thầy cùng lúc, mỗi thầy một ít.", "Chưa làm đã bàn chuyện mở lớp dạy người."]},
 canhBao: {y: "Khi đã nắm căn bản và muốn tự làm thật, đọc", ma: "ks2"}},
{ma: "ks4", nhom: "ks", ten: "Mới có chút đà đã muốn làm lớn ngay", que: [{n: 34, hao: 1}, {n: 42, hao: 1}],
 viSao: "Quẻ Đại Tráng là sấm trên trời: sức đang lớn. Nhưng hào đầu mạnh ở ngón chân, ở dưới thấp mà đã muốn đi. Thoán nói mạnh phải đi với chính. Đại tượng dạy việc trái lễ thì không làm. Quẻ Ích hào đầu cho phép làm việc lớn, nhưng phải rất tốt mới không lỗi.",
 trich: {n: 34, hao: 1, zh: "壯于趾，征凶，有孚", hv: "Tráng vu chỉ, chinh hung, hữu phu.", dich: "Mạnh ở ngón chân mà đã đi thì xấu; điều ấy chắc chắn."},
 ungXu: {nen: ["Nhân đôi, không nhân mười: mở rộng đúng bằng phần đã chạy tốt.", "Hỏi người đã làm lớn thất bại một lần, nghe họ kể vì sao.", "Viết ra ba điều sẽ hỏng nếu làm lớn, và cách đỡ từng điều."],
  tranh: ["Ký hợp đồng dài, thuê người đông, vay nhiều cùng một lúc."]},
 canhBao: {y: "Khi đã có người theo và lực thật, cách tiến đúng là từng bước; đọc", ma: "ks5"}},
{ma: "ks5", nhom: "ks", ten: "Việc mới, muốn tiến từng bước cho chắc", que: [{n: 53}, {n: 46}],
 viSao: "Quẻ Tiệm là cây trên núi: lớn chậm mà cao. Tượng là chim hồng bay từ bờ nước lên gò cao, từng chặng có thứ tự. Lời quẻ ví con gái về nhà chồng đúng lễ. Quẻ Thăng (cây mọc trong đất) cũng dạy tích nhỏ thành lớn.",
 trich: {n: 53, zh: "女歸吉，利貞", hv: "Nữ quy cát, lợi trinh.", dich: "Con gái về nhà chồng đúng lễ thì tốt; giữ chính thì lợi."},
 ungXu: {nen: ["Chia việc thành chặng, mỗi chặng có dấu hiệu xong rõ ràng.", "Xong chặng này mới mở chặng sau, dù đang hứng.", "Giữ nếp: cùng giờ, cùng cách, ngày nào cũng một ít."],
  tranh: ["Nhảy cóc chặng vì có người hối hoặc vì thấy người khác nhanh hơn."]},
 canhBao: {y: "Nếu bắt đầu nóng ruột, đốt cháy giai đoạn, đọc", ma: "ks4"}},
{ma: "ks6", nhom: "ks", ten: "Bắt đầu lại sau một lần thất bại", que: [{n: 24, hao: 1}],
 viSao: "Quẻ Phục là sấm trong đất: một hào dương mới sinh dưới năm hào âm. Tượng là Đông chí, ngày dài trở lại. Thoán nói ở Phục thấy được lòng trời đất. Hào đầu: đi chưa xa đã quay lại thì chưa đến mức phải hối. Quay lại càng sớm càng rẻ.",
 trich: {n: 24, hao: 1, zh: "不遠復，无祇悔，元吉", hv: "Bất viễn phục, vô kỳ hối, nguyên cát.", dich: "Đi chưa xa mà quay lại ngay, chưa đến nỗi phải hối; rất tốt."},
 ungXu: {nen: ["Viết một trang: lần trước hỏng ở đâu, dấu hiệu nào mình đã bỏ qua.", "Bắt đầu lại nhỏ hơn lần trước, dùng đúng bài học ấy.", "Nghỉ đủ trước khi làm lại; Phục là đóng cửa ải ngày Đông chí."],
  tranh: ["Làm lại y như cũ chỉ với nhiều tiền hơn."]},
 canhBao: {y: "Nếu lỗi cũ lặp lại lần thứ ba, thứ tư, phải xét có nên làm việc này nữa không; đọc", ma: "lk1"}},
{ma: "ks7", nhom: "ks", ten: "Làm việc mới mà trong lòng có chỗ tính toán không ngay", que: [{n: 25}],
 viSao: "Quẻ Vô Vọng là sấm đi dưới trời: muôn vật động theo lẽ tự nhiên, không càn bậy. Thoán nói không chính thì có họa, đi đâu cũng không lợi. Đại tượng dạy thuận thời mà nuôi vật. Việc có chỗ không ngay thì dù khéo đến đâu cũng mang mầm họa.",
 trich: {n: 25, zh: "其匪正有眚，不利有攸往", hv: "Kỳ phỉ chính hữu sảnh, bất lợi hữu du vãng.", dich: "Nếu không ngay thẳng thì có tai họa; đi tới không lợi."},
 ungXu: {nen: ["Nêu thẳng chỗ mình thấy chưa ngay: ai bị thiệt, điều gì phải giấu.", "Bỏ phần không ngay dù việc chậm lại hay bớt lời.", "Chỉ làm điều mình dám kể cho người nhà nghe."],
  tranh: ["Tự nhủ ai cũng làm thế.", "Chờ có lời rồi mới sửa."]},
 canhBao: {y: "Nếu đã ngay thẳng mà vẫn gặp họa không do mình, đọc", ma: "tc8"}},

// ===== Chờ thời =====
{ma: "ct1", nhom: "ct", ten: "Thời chưa đến, phải đợi mà sốt ruột", que: [{n: 5}, {n: 9}],
 viSao: "Quẻ Nhu là mây lên trời mà chưa mưa. Tượng là hiểm ở trước, sức mạnh ở dưới biết dừng. Thoán nói đợi mà có lòng tin thì sáng và thông. Đại tượng dạy ăn uống yên vui trong lúc chờ. Đợi là một việc, không phải không làm gì.",
 trich: {n: 5, zh: "有孚，光亨。貞吉", hv: "Hữu phu, quang hanh. Trinh cát.", dich: "Có lòng tin thì sáng và thông; giữ chính thì tốt."},
 ungXu: {nen: ["Đặt mốc: đợi đến ngày nào, thấy dấu hiệu nào thì làm.", "Dùng thời gian chờ để chuẩn bị: học, tích tiền, tìm người.", "Giữ nếp sống đều, ăn ngủ đủ; chờ lâu cần sức."],
  tranh: ["Làm việc gì đó chỉ để khỏi cảm thấy đang đợi.", "Hỏi đi hỏi lại người khác xem đã đến lúc chưa."]},
 canhBao: {y: "Nếu đợi lâu quá, bắt đầu muốn liều cho xong, đọc", ma: "ct2"}},
{ma: "ct2", nhom: "ct", ten: "Đợi quá lâu, sắp hết kiên nhẫn, muốn liều", que: [{n: 5, hao: 3}],
 viSao: "Hào ba quẻ Nhu ở sát mép hiểm: đợi ở bùn lầy. Càng nhích tới càng lún, và tự rước nguy về. Thoán quẻ Nhu nói hiểm ở trước mặt, cứng mà không sa vào mới không khốn. Lúc này cái nguy không ở việc, mà ở chính sự sốt ruột.",
 trich: {n: 5, hao: 3, zh: "需于泥，致寇至", hv: "Nhu vu nê, trí khấu chí.", dich: "Đợi ở bùn lầy, tự rước giặc đến."},
 ungXu: {nen: ["Lùi một bước về chỗ khô: hoãn mọi quyết định lớn trong hai tuần.", "Kể với một người điềm tĩnh, để họ nghe mình sốt ruột đến đâu.", "Xem lại mốc đã đặt lúc đầu; chưa tới mốc thì chưa làm."],
  tranh: ["Ký, vay, mua, cưới chỉ vì không chịu được việc đợi thêm."]},
 canhBao: {y: "Nếu đã sa vào chỗ nguy, khó chồng khó, đọc", ma: "tc5"}},
{ma: "ct3", nhom: "ct", ten: "Việc bị cản bởi trở ngại nhỏ, mãi không xong", que: [{n: 9}],
 viSao: "Quẻ Tiểu Súc là gió đi trên trời: một hào âm nhỏ kìm năm hào dương. Tượng là mây dày mà chưa mưa. Thoán nói sức mềm giữ được chỗ, trên dưới hưởng ứng, nên vẫn thông. Đại tượng dạy trau dồi văn đức trong lúc bị cản. Cái cản nhỏ, nhưng chưa gỡ được bằng sức.",
 trich: {n: 9, zh: "密雲不雨，自我西郊", hv: "Mật vân bất vũ, tự ngã tây giao.", dich: "Mây dày mà chưa mưa, kéo từ cõi tây của ta đến."},
 ungXu: {nen: ["Gọi tên đúng cái cản: một người, một giấy tờ, một khoản tiền.", "Gỡ bằng mềm: hỏi, nhờ, chờ đúng người xử; không húc.", "Trong lúc chờ, làm phần không bị cản cho xong trước."],
  tranh: ["Đổ lỗi cho cả hệ thống khi cái cản chỉ là một chỗ."]},
 canhBao: {y: "Khi mưa đã rơi, việc đã thành, chỗ nguy mới là tự mãn; đọc", ma: "lk4"}},
{ma: "ct4", nhom: "ct", ten: "Mọi cửa đều đóng, bế tắc", que: [{n: 12}, {n: 36}],
 viSao: "Quẻ Bĩ là trời đất không giao: trên đi lên, dưới đi xuống, không gặp nhau. Lời quẻ nói cái lớn đi, cái nhỏ đến. Đại tượng dạy thu đức lại để tránh nạn, không lấy lộc làm vinh. Lúc này cố mở cửa là tốn sức vô ích.",
 trich: {n: 12, zh: "大往小來", hv: "Đại vãng tiểu lai.", dich: "Cái lớn đi, cái nhỏ đến."},
 ungXu: {nen: ["Thu nhỏ: giữ việc cốt lõi, cắt chi tiêu, bớt lời hứa.", "Giữ nguyên tắc; không đổi mình để lấy lòng người đang ép.", "Dùng thời gian tắc để học và chăm sức khỏe."],
  tranh: ["Nhận lộc, nhận chức từ chỗ mình biết là sai để thoát tắc.", "Than mãi với mọi người; tắc là thời, không phải lỗi riêng."]},
 canhBao: {y: "Khi thấy dấu hiệu bế tắc lung lay, đọc", ma: "ct5"}},
{ma: "ct5", nhom: "ct", ten: "Có dấu hiệu khó khăn sắp qua, nên làm gì", que: [{n: 12, hao: 5}, {n: 11}],
 viSao: "Hào năm quẻ Bĩ là lúc người có đức làm cho bế tắc dừng lại. Nhưng lời hào dặn luôn tự nhủ sắp mất rồi, như buộc dây vào gốc dâu. Thoán quẻ Bĩ nói đạo tiểu nhân lớn, đạo quân tử tiêu; lúc đổi chiều dễ chủ quan nhất. Hệ từ cũng dạy yên không quên nguy.",
 trich: {n: 12, hao: 5, zh: "其亡其亡，繫于包桑", hv: "Kỳ vong kỳ vong, hệ vu bao tang.", dich: "Luôn nghĩ sắp mất rồi, sắp mất rồi; như buộc vào gốc dâu cho vững."},
 ungXu: {nen: ["Mở lại từng cửa một, cửa nào chắc nhất trước.", "Giữ nếp tiết kiệm của thời tắc thêm sáu tháng.", "Ghi lại ai đã giúp mình lúc tắc, trả ơn trước khi làm việc mới."],
  tranh: ["Bù lại thời khó bằng tiêu xài và hứa hẹn."]},
 canhBao: {y: "Khi đã thông, trên dưới một lòng, đọc", ma: "ld1"}},
{ma: "ct6", nhom: "ct", ten: "Thời tối, người ngay bị chèn ép, nên giấu mình", que: [{n: 36}, {n: 12}],
 viSao: "Quẻ Minh Di là ánh sáng lặn vào đất. Tượng là người sáng ở dưới kẻ tối ở trên. Lời quẻ chỉ nói một câu: giữ chính trong gian nan thì lợi. Đại tượng dạy đến với mọi người mà dùng vẻ tối để giữ sáng bên trong. Hào năm lấy chuyện Cơ Tử giả tối để giữ mình.",
 trich: {n: 36, zh: "利艱貞", hv: "Lợi gian trinh.", dich: "Giữ chính trong gian nan thì lợi."},
 ungXu: {nen: ["Làm đúng việc, nói ít, không phô tài trước người đang ép.", "Giữ một việc riêng nuôi sức mình: học, viết, nghề tay trái.", "Giữ liên hệ với vài người ngay thẳng, không bàn chuyện cấp trên."],
  tranh: ["Đối đầu công khai khi chưa có đường lui.", "Đổi mình thành kẻ tối để được yên."]},
 canhBao: {y: "Nếu ở lại cũng không giữ được mình, ra đi là một đường; đọc", ma: "lk7"}},
{ma: "ct7", nhom: "ct", ten: "Cần dừng hẳn lại, nghỉ, tĩnh tâm", que: [{n: 52}],
 viSao: "Quẻ Cấn là hai núi chồng nhau: dừng. Lời quẻ nói dừng ở lưng, không thấy thân mình; đi trong sân không thấy người: lòng không bị ngoại vật kéo. Thoán nói dừng đúng lúc, động đúng lúc, động tĩnh không lỡ thời. Đại tượng dạy nghĩ không ra ngoài vị trí của mình.",
 trich: {n: 52, zh: "艮其背，不獲其身", hv: "Cấn kỳ bối, bất hoạch kỳ thân.", dich: "Dừng ở lưng, không thấy thân mình: lòng yên, không bị kéo đi."},
 ungXu: {nen: ["Hẹn một kỳ nghỉ có ngày bắt đầu và ngày hết, không nghỉ mơ hồ.", "Tắt bớt tin, bớt gặp; mỗi ngày một việc tay chân.", "Trong lúc dừng, chỉ hỏi một câu: việc nào là việc của mình."],
  tranh: ["Nghỉ mà vẫn mở điện thoại xem việc mỗi giờ.", "Dừng thành bỏ hẳn mà không nói với ai."]},
 canhBao: {y: "Khi nghỉ đủ và thấy đà trở lại, bắt đầu lại từ việc nhỏ; đọc", ma: "ks6"}},

// ===== Hợp tác và quan hệ =====
{ma: "ht1", nhom: "ht", ten: "Nên theo ai, gia nhập nhóm nào", que: [{n: 8}, {n: 13}],
 viSao: "Quẻ Tỷ là nước trên đất: nước tụ về chỗ trũng, người tụ về người đáng theo. Lời quẻ bảo xét kỹ như bói lại lần nữa: người đứng đầu có đủ đức lớn, lâu dài, chính bền không. Kẻ đến sau thì xấu. Quẻ Đồng Nhân dạy hợp với người ở chỗ rộng, không ở chỗ hẹp.",
 trich: {n: 8, zh: "原筮元永貞，无咎", hv: "Nguyên phệ nguyên vĩnh trinh, vô cữu.", dich: "Xét kỹ lại xem có đủ đức lớn, lâu dài, chính bền; như thế thì không lỗi."},
 ungXu: {nen: ["Xét người đứng đầu ba điều: có lớn không, có bền không, có ngay không.", "Hỏi người đã đi theo họ ba năm, nghe cả lời chê.", "Đã quyết theo thì đến sớm, góp thật, không đứng ngoài xem."],
  tranh: ["Theo vì nhóm đông, vì bạn mình ở đó, vì lời hứa chia phần."]},
 canhBao: {y: "Nếu chọn nhóm chỉ vì quen biết, họ hàng, đọc", ma: "ht2"}},
{ma: "ht2", nhom: "ht", ten: "Chỉ hợp tác với người quen, người nhà, phe mình", que: [{n: 13, hao: 2}],
 viSao: "Quẻ Đồng Nhân là lửa dưới trời: lửa bốc lên hợp với trời ở chỗ rộng. Lời quẻ khen hòa đồng ở nơi đồng nội. Hào hai lại chỉ hòa với người trong họ: đáng tiếc, vì chật. Đại tượng dạy xếp theo loài để biết người, không để đóng cửa.",
 trich: {n: 13, hao: 2, zh: "同人于宗，吝", hv: "Đồng nhân vu tông, lận.", dich: "Chỉ hòa với người trong họ hàng, đáng tiếc."},
 ungXu: {nen: ["Mỗi việc mới, mời một người ngoài vòng quen biết tham gia.", "Giao việc theo người làm được, không theo người thân.", "Viết quy tắc chung để người ngoài vào không phải xin ai."],
  tranh: ["Chia lợi theo thân sơ.", "Giấu thông tin với người không cùng phe."]},
 canhBao: {y: "Khi nhóm thân quen bắt đầu chia phe, lòng người tan, đọc", ma: "ld8"}},
{ma: "ht3", nhom: "ht", ten: "Tình cảm mới chớm, có nên tiến tới ngay", que: [{n: 31, hao: 2}],
 viSao: "Quẻ Hàm là đầm trên núi: núi vững đỡ nước, hai bên cảm nhau tự nhiên. Thoán nói mềm trên cứng dưới, hai khí cảm ứng mà hợp. Sáu hào kể cảm từ ngón chân lên đến má lưỡi. Hào hai cảm ở bắp chân: mới rung động mà chân đã muốn chạy theo, nên xấu; ở yên thì tốt.",
 trich: {n: 31, hao: 2, zh: "咸其腓，凶，居吉", hv: "Hàm kỳ phì, hung, cư cát.", dich: "Cảm ở bắp chân, chạy theo thì xấu; ở yên thì tốt."},
 ungXu: {nen: ["Gặp đều, chuyện thật, không hứa gì lớn trong ba tháng đầu.", "Xem người ấy đối với người nhà, người giúp việc, người lạ thế nào.", "Để người kia cũng bước tới; cảm là hai chiều."],
  tranh: ["Chuyển nhà, chuyển tiền, bỏ việc vì một người mới quen."]},
 canhBao: {y: "Khi tính chuyện lâu dài, cưới hỏi, đọc", ma: "gi5"}},
{ma: "ht4", nhom: "ht", ten: "Quan hệ lâu năm nhạt dần, muốn giữ", que: [{n: 32, hao: 3}],
 viSao: "Quẻ Hằng là sấm và gió: hai thứ luôn động mà đi cùng nhau mãi. Thoán nói bền là giữ đạo thường mà vẫn biến thông, như trời đất lâu dài. Đại tượng dạy đứng vững, không đổi phương hướng. Hào ba cảnh báo không giữ bền đức mình thì chuốc hổ thẹn.",
 trich: {n: 32, hao: 3, zh: "不恆其德，或承之羞，貞吝", hv: "Bất hằng kỳ đức, hoặc thừa chi tu, trinh lận.", dich: "Không giữ bền đức của mình, có khi chuốc lấy hổ thẹn; cố giữ thì đáng tiếc."},
 ungXu: {nen: ["Giữ một nếp chung nhỏ, đều: bữa cơm tuần, cuộc gọi tháng.", "Hỏi thẳng người kia: điều gì ở mình đã khác, điều gì họ thiếu.", "Đổi cách gặp, không đổi lòng: Hằng là biến thông trong cái bền."],
  tranh: ["Lấy công cũ ra kể để đòi người kia giữ.", "Im lặng chờ người kia nhận ra."]},
 canhBao: {y: "Nếu hai bên đã khác hẳn đường đi, đọc", ma: "ht5"}},
{ma: "ht5", nhom: "ht", ten: "Hai bên khác ý, hiểu lầm nhau", que: [{n: 38}],
 viSao: "Quẻ Khuê là lửa trên đầm: lửa bốc lên, nước chảy xuống, hai thứ quay lưng. Lời quẻ chỉ bảo việc nhỏ thì tốt. Thoán nói trời đất khác mà việc cùng, nam nữ khác mà chí thông. Đại tượng dạy đồng ở chỗ chung, khác ở chỗ riêng. Khác không phải là thù.",
 trich: {n: 38, zh: "小事吉", hv: "Tiểu sự cát.", dich: "Việc nhỏ thì tốt."},
 ungXu: {nen: ["Làm cùng một việc nhỏ có điểm chung trước; chưa bàn việc lớn.", "Nói rõ chỗ mình hiểu khác, hỏi họ hiểu thế nào; không đoán.", "Giữ lễ: đúng giờ, đúng lời, dù còn khác ý."],
  tranh: ["Ép thống nhất ngay bằng số đông hay chức vụ.", "Kể chuyện khác ý với người thứ ba."]},
 canhBao: {y: "Nếu đã thành đối đầu, có người tính kiện, đọc", ma: "tc1"}},
{ma: "ht6", nhom: "ht", ten: "Bị hiểu lầm, bị nói xấu", que: [{n: 5, hao: 2}, {n: 47}],
 viSao: "Hào hai quẻ Nhu đợi ở bãi cát: xa hiểm, nhưng có chút lời ra tiếng vào, cuối cùng vẫn tốt. Tiểu tượng nói ở giữa mà rộng lòng thì lời tiếng tự tan. Quẻ Khốn còn nói rõ hơn: lúc khốn, có nói cũng không ai tin, nên bớt nói, giữ chí.",
 trich: {n: 5, hao: 2, zh: "需于沙，小有言，終吉", hv: "Nhu vu sa, tiểu hữu ngôn, chung cát.", dich: "Đợi ở bãi cát, có chút lời ra tiếng vào; cuối cùng tốt."},
 ungXu: {nen: ["Nói một lần, rõ, với người cần biết; rồi thôi.", "Làm việc tiếp cho tốt; kết quả là lời cải chính bền nhất.", "Ghi lại sự việc có ngày giờ, để khi cần có bằng chứng."],
  tranh: ["Đi giải thích với từng người.", "Nói xấu lại."]},
 canhBao: {y: "Nếu lời nói xấu gây hại thật (mất việc, mất khách), đọc", ma: "tc1"}},
{ma: "ht7", nhom: "ht", ten: "Có người mạnh rủ làm chung, có nên nhận", que: [{n: 44}, {n: 17}],
 viSao: "Quẻ Cấu là gió dưới trời: một hào âm mới hiện dưới năm hào dương, gặp gỡ bất ngờ. Lời quẻ cảnh báo người con gái quá mạnh thì chớ lấy: cái nhỏ mà lấn át sẽ lớn dần. Thoán nói gặp đúng đạo thì thiên hạ hóa. Quẻ Tùy dạy theo đúng người thì có công.",
 trich: {n: 44, zh: "女壯，勿用取女", hv: "Nữ tráng, vật dụng thủ nữ.", dich: "Người con gái quá mạnh, lấn lướt, thì chớ lấy làm vợ."},
 ungXu: {nen: ["Hỏi họ cần gì ở mình; nếu không trả lời rõ, đó là dấu hiệu.", "Thử một việc nhỏ có hạn trước khi ký lâu dài.", "Giữ phần quyết định về việc của mình, dù họ góp nhiều hơn."],
  tranh: ["Nhận vì họ mạnh, vì sợ mất cơ hội.", "Giao hết sổ sách, khách hàng ngay buổi đầu."]},
 canhBao: {y: "Khi đã xét kỹ và quyết theo, cách theo đúng ở mục", ma: "ht1"}},
{ma: "ht8", nhom: "ht", ten: "Muốn xây lòng tin với đối tác, khách hàng", que: [{n: 61, hao: 2}],
 viSao: "Quẻ Trung Phu là gió trên đầm: lòng rỗng ở giữa, tin thật. Lời quẻ nói lòng tin cảm được đến heo cá. Hào hai là hạc mẹ kêu trong bóng râm, hạc con họa theo: không cần thấy mặt mà vẫn ứng. Hệ từ bình hào này: lời nói việc làm là then máy của người quân tử.",
 trich: {n: 61, hao: 2, zh: "鳴鶴在陰，其子和之", hv: "Minh hạc tại âm, kỳ tử họa chi.", dich: "Hạc kêu trong bóng râm, hạc con họa theo."},
 ungXu: {nen: ["Hứa ít hơn khả năng một bậc, rồi làm đủ.", "Báo tin xấu sớm hơn tin tốt.", "Giữ một việc nhỏ đều đặn người kia thấy được: đúng giờ, đúng hạn."],
  tranh: ["Nói hay hơn làm.", "Khoe quan hệ, khoe khách lớn."]},
 canhBao: {y: "Nếu lời hứa bắt đầu vượt sức mình, đọc", ma: "ks4"}},

// ===== Tranh chấp và khó khăn =====
{ma: "tc1", nhom: "tc", ten: "Có nên kiện, có nên theo tranh chấp đến cùng", que: [{n: 6}, {n: 38}],
 viSao: "Quẻ Tụng là trời và nước đi ngược: trên cứng, dưới hiểm, không ai nhường. Lời quẻ nói có lòng thành mà bị lấp, dừng giữa chừng thì tốt, theo đến cùng thì xấu. Đại tượng dạy việc gì cũng tính kỹ từ đầu để khỏi tụng. Hào trên được ban đai da rồi bị tước ba lần trong một buổi.",
 trich: {n: 6, zh: "有孚，窒，惕，中吉，終凶", hv: "Hữu phu, trất, dịch, trung cát, chung hung.", dich: "Có lòng thành mà bị ngăn lấp, nên lo sợ; dừng giữa chừng thì tốt, theo đến cùng thì xấu."},
 ungXu: {nen: ["Tính trước: thắng rồi được gì, mất gì, mất bao lâu.", "Tìm người có uy tín cả hai bên nghe để phân xử.", "Nhường phần nhỏ để giữ phần lớn và giữ sức."],
  tranh: ["Kiện vì tức.", "Kéo người thân vào cuộc."]},
 canhBao: {y: "Nếu biết mình yếu thế, lánh đi còn hơn thua đau; đọc", ma: "lk1"}},
{ma: "tc2", nhom: "tc", ten: "Có kẻ cố tình gây rối, phá đám", que: [{n: 21}, {n: 55}],
 viSao: "Quẻ Phệ Hạp là sấm và chớp: có vật kẹt giữa hai hàm thì phải cắn vỡ. Lời quẻ nói lợi dùng hình ngục. Thoán nói cứng mềm chia rõ, động mà sáng. Đại tượng dạy làm rõ hình phạt, chỉnh pháp luật. Kẻ gây rối phải xử công khai theo luật, không xử ngầm.",
 trich: {n: 21, zh: "利用獄", hv: "Lợi dụng ngục.", dich: "Nên dùng đến pháp luật, hình phạt."},
 ungXu: {nen: ["Thu bằng chứng: tin nhắn, giấy tờ, người chứng, có ngày giờ.", "Dùng đúng đường: nội quy, hợp đồng, cơ quan có quyền.", "Cảnh báo một lần bằng văn bản trước khi xử."],
  tranh: ["Xử nóng, xử riêng, xử quá tay rồi thành người có lỗi.", "Nhờ kẻ mạnh khác dọa giúp."]},
 canhBao: {y: "Nếu kẻ gây rối là người dưới mình, cách phạt ở mục", ma: "ld2"}},
{ma: "tc3", nhom: "tc", ten: "Gặp trở ngại lớn trước mặt, không vượt được", que: [{n: 39, hao: 1}],
 viSao: "Quẻ Kiển là nước trên núi: trước mặt hiểm, sau lưng dốc, chân khó đi. Thoán nói thấy hiểm mà biết dừng là khôn. Đại tượng dạy quay về xét mình, sửa đức. Hào đầu: đi thì gặp khó, quay lại thì được khen. Lời quẻ bảo tìm người lớn mà hỏi.",
 trich: {n: 39, hao: 1, zh: "往蹇，來譽", hv: "Vãng kiển, lai dự.", dich: "Đi tới thì gặp khó, quay lại thì được khen."},
 ungXu: {nen: ["Dừng hẳn việc húc vào trở ngại; đổi hướng tây nam, chỗ dễ hơn.", "Hỏi một người từng vượt trở ngại giống thế.", "Xét mình: khó này do thời hay do cách mình làm."],
  tranh: ["Dốc nốt sức còn lại để vượt bằng được."]},
 canhBao: {y: "Khi khó khăn bắt đầu tan, đọc", ma: "tc4"}},
{ma: "tc4", nhom: "tc", ten: "Khó khăn vừa qua, phải dọn dẹp hậu quả", que: [{n: 40}],
 viSao: "Quẻ Giải là sấm mưa nổi lên: băng tan, cây cỏ nứt vỏ. Lời quẻ nói không còn chỗ phải đi thì về nếp cũ; còn việc thì làm sớm. Đại tượng dạy tha lỗi, giảm tội. Khó qua rồi, việc đầu là gỡ nhanh phần còn vướng, rồi khoan dung.",
 trich: {n: 40, zh: "有攸往，夙吉", hv: "Hữu du vãng, túc cát.", dich: "Còn việc phải làm thì làm sớm mới tốt."},
 ungXu: {nen: ["Liệt kê việc còn vướng, làm trong hai tuần, không để dây dưa.", "Tha cho người lỡ lầm trong lúc khó; chỉ xử kẻ cố tình.", "Trở về nếp thường: giờ giấc, sổ sách, bữa cơm."],
  tranh: ["Kể mãi chuyện khó.", "Trả thù người đã quay lưng."]},
 canhBao: {y: "Nếu dọn xong mà ôm đồm cả việc lẫn của, đọc", ma: "tb3"}},
{ma: "tc5", nhom: "tc", ten: "Khó chồng khó, nguy hiểm vây quanh", que: [{n: 29}, {n: 47}],
 viSao: "Quẻ Khảm là nước chồng nước: hiểm trong hiểm. Lời quẻ nói giữ được lòng tin thì chỉ cái lòng ấy là thông. Thoán nói nước chảy mà không đầy tràn, qua hiểm mà không mất tin. Đại tượng dạy giữ đức thường, luyện việc dạy. Nước không cố, chỉ chảy tiếp.",
 trich: {n: 29, zh: "有孚，維心亨。行有尚", hv: "Hữu phu, duy tâm hanh. Hành hữu thượng.", dich: "Có lòng tin, chỉ cái lòng ấy là thông; cứ đi thì được trọng."},
 ungXu: {nen: ["Mỗi ngày một việc nhỏ chắc chắn làm được; lấy đó làm chỗ bám.", "Nói thật với người có thể giúp: mình đang ở đâu, cần gì.", "Giữ sức khỏe trước mọi thứ; hiểm kéo dài cần người còn đứng được."],
  tranh: ["Liều một lần cho xong.", "Giấu tình trạng với người nhà."]},
 canhBao: {y: "Nếu đã kiệt sức, thiếu tiền, nói không ai nghe, đọc", ma: "tc6"}},
{ma: "tc6", nhom: "tc", ten: "Kiệt sức, thiếu tiền, nói không ai tin", que: [{n: 47}, {n: 29}],
 viSao: "Quẻ Khốn là đầm không nước: cạn kiệt. Lời quẻ nói người lớn giữ chính thì vẫn thông, nhưng có nói cũng không ai tin. Thoán nói cứng bị che lấp mà vẫn vui giữ đạo. Đại tượng dạy liều cả mạng để giữ chí. Khốn là lúc đo xem mình thật tin điều gì.",
 trich: {n: 47, zh: "貞大人吉，无咎，有言不信", hv: "Trinh đại nhân cát, vô cữu, hữu ngôn bất tín.", dich: "Người lớn giữ chính thì tốt, không lỗi; nhưng có nói cũng không ai tin."},
 ungXu: {nen: ["Bớt nói, bớt hứa, bớt giải thích; làm việc nhỏ thấy được.", "Cắt chi tiêu đến mức sống được, giữ việc nuôi thân.", "Giữ một niềm tin cốt lõi làm chỗ đứng; đừng bán nó lúc này."],
  tranh: ["Vay nóng để giữ thể diện.", "Đổi nguyên tắc để được người ta tin lại."]},
 canhBao: {y: "Khi khốn bắt đầu chuyển, có người đến giúp, đọc", ma: "tc4"}},
{ma: "tc7", nhom: "tc", ten: "Biến cố bất ngờ ập đến: tai nạn, tin dữ, mất việc", que: [{n: 51}],
 viSao: "Quẻ Chấn là sấm chồng sấm. Lời quẻ nói sấm đến làm người sợ rụt, rồi lại cười nói được. Sấm vang trăm dặm mà người chủ tế không đánh rơi muỗng rượu: giữ được việc cốt lõi giữa cơn chấn động. Đại tượng dạy lo sợ mà sửa mình, tự xét.",
 trich: {n: 51, zh: "震來虩虩，笑言啞啞", hv: "Chấn lai hích hích, tiếu ngôn ách ách.", dich: "Sấm đến làm sợ hãi rụt rè; rồi lại cười nói vui vẻ."},
 ungXu: {nen: ["Hai ngày đầu chỉ lo an toàn người và việc cốt lõi; chưa quyết gì khác.", "Viết ra điều gì vẫn còn, ai vẫn ở bên.", "Sau cơn, hỏi một câu: biến cố này báo mình phải sửa gì."],
  tranh: ["Quyết việc lớn trong tuần đầu.", "Tìm người để đổ lỗi."]},
 canhBao: {y: "Nếu biến cố làm mất của, đọc", ma: "lk5"}},
{ma: "tc8", nhom: "tc", ten: "Gặp họa không do mình gây, bị vạ lây, bị nghi oan", que: [{n: 25, hao: 3}],
 viSao: "Quẻ Vô Vọng là không càn bậy. Hào ba kể chuyện người buộc bò, kẻ qua đường dắt mất, người trong ấp bị nghi. Mình không làm sai mà vẫn mang vạ. Thoán nói động mà cứng, trên dưới đều ứng, thuận thời thì thông. Họa ấy là của thời, không phải của mình.",
 trich: {n: 25, hao: 3, zh: "无妄之災，或繫之牛，行人之得，邑人之災", hv: "Vô vọng chi tai, hoặc hệ chi ngưu, hành nhân chi đắc, ấp nhân chi tai.", dich: "Họa không do mình: có người buộc bò, kẻ qua đường dắt mất, người trong ấp bị vạ."},
 ungXu: {nen: ["Nói sự thật một lần, có bằng chứng; không thêm bớt.", "Chịu phần thiệt trước mắt nếu cần, giữ sự ngay thẳng về lâu.", "Chữa bệnh, sửa việc đúng cách; không chạy vạy theo lời đồn."],
  tranh: ["Làm điều không ngay để gỡ oan cho nhanh.", "Oán người, oán trời rồi bỏ việc."]},
 canhBao: {y: "Nếu phải ra tòa minh oan, cách giữ mình ở mục", ma: "tc1"}},

// ===== Tiền bạc =====
{ma: "tb1", nhom: "tb", ten: "Thu ít, phải thắt lưng buộc bụng", que: [{n: 60}, {n: 41}],
 viSao: "Quẻ Tiết là nước trên đầm: đầm có bờ nên nước không tràn. Thoán nói đặt mức độ thì không hại của, không hại dân. Lời quẻ nói tiết chế đến mức khắc khổ thì không giữ được lâu. Đại tượng dạy đặt ra con số và mức độ. Tiết là có bờ, không phải khô cạn.",
 trich: {n: 60, zh: "苦節不可貞", hv: "Khổ tiết bất khả trinh.", dich: "Tiết chế đến mức khắc khổ thì không thể giữ lâu."},
 ungXu: {nen: ["Đặt con số cụ thể: tháng này tiêu bao nhiêu, ghi từng khoản.", "Cắt khoản lớn trước, giữ khoản nhỏ làm vui.", "Giữ một khoản đều cho sức khỏe và học hành."],
  tranh: ["Thắt đến mức ốm, mất quan hệ, rồi bung ra tiêu bù."]},
 canhBao: {y: "Nếu phải bớt cả phần cốt lõi để trả nợ hay lo việc chung, đọc", ma: "tb2"}},
{ma: "tb2", nhom: "tb", ten: "Phải bớt của mình để lo việc chung hoặc trả nợ", que: [{n: 41}],
 viSao: "Quẻ Tổn là đầm dưới núi: bớt dưới để thêm trên. Lời quẻ nói bớt mà có lòng thành thì rất tốt; hai bát cơm cũng dâng cúng được. Thoán nói bớt thêm đầy vơi đi cùng thời. Đại tượng dạy nén giận, bớt dục. Bớt đúng chỗ là thêm.",
 trich: {n: 41, zh: "二簋可用享", hv: "Nhị quỹ khả dụng hưởng.", dich: "Hai bát cơm cũng đủ dâng cúng: ít mà thành thì vẫn trọn lễ."},
 ungXu: {nen: ["Trả nợ theo thứ tự: lãi cao trước, người nghèo hơn mình trước.", "Nói rõ với chủ nợ, người nhà: trả bao nhiêu, bao lâu.", "Bớt từ cái dễ bớt nhất: ăn ngoài, đồ mới, lời hứa."],
  tranh: ["Vay chỗ này đắp chỗ kia.", "Bớt phần của người phụ thuộc mình trước phần của mình."]},
 canhBao: {y: "Khi đã trả xong và có dư, cách chia ở mục", ma: "tb6"}},
{ma: "tb3", nhom: "tb", ten: "Làm ăn đang lên, nhiều của, cần giữ", que: [{n: 14, hao: 4}, {n: 15}],
 viSao: "Quẻ Đại Hữu là lửa trên trời: sáng rộng, có nhiều. Thoán nói mềm ở ngôi tôn, trên dưới ứng theo. Đại tượng dạy ngăn ác, nêu thiện. Hào bốn ở gần ngôi tôn mà không phô cái đầy của mình nên không lỗi. Quẻ Khiêm đứng ngay sau Đại Hữu: có lớn thì phải khiêm.",
 trich: {n: 14, hao: 4, zh: "匪其尫，无咎", hv: "Phỉ kỳ bàng, vô cữu.", dich: "Không phô trương sự đầy thịnh, không lỗi."},
 ungXu: {nen: ["Giữ mức sống như hai năm trước; để tiền lớn vào chỗ chắc.", "Chia một phần đều đặn cho người giúp mình và việc chung.", "Ghi rõ của ai, nợ ai; của nhiều dễ lẫn."],
  tranh: ["Khoe, mua sắm để người ta thấy.", "Cho vay, bảo lãnh vì ngại từ chối."]},
 canhBao: {y: "Nếu muốn đem phần lớn của ra đầu tư việc lớn, đọc", ma: "tb4"}},
{ma: "tb4", nhom: "tb", ten: "Có cơ hội lớn, định dốc hết vốn", que: [{n: 28, hao: 3}, {n: 27, hao: 5}],
 viSao: "Quẻ Đại Quá là đầm ngập cây: cái lớn vượt mức, xà nóc cong. Thoán nói gốc ngọn yếu mà giữa nặng. Hào ba xà oằn thì xấu: gánh quá sức. Hào năm quẻ Di dặn ở yên giữ chính, không qua sông lớn khi nguồn nuôi còn trái lẽ.",
 trich: {n: 28, hao: 3, zh: "棟橈，凶", hv: "Đống nạo, hung.", dich: "Xà nóc cong oằn vì chịu quá nặng, xấu."},
 ungXu: {nen: ["Chỉ bỏ phần mất đi vẫn sống được; phần còn lại không chạm.", "Hỏi hai người đã mất tiền vì cơ hội tương tự.", "Đặt ngưỡng dừng trước khi vào: lỗ bao nhiêu thì rút."],
  tranh: ["Vay thêm để dốc.", "Tin lời đã có người lớn bảo đảm."]},
 canhBao: {y: "Nếu đã lỡ dốc hết và mất, đọc", ma: "lk5"}},
{ma: "tb5", nhom: "tb", ten: "Nguồn thu lâu dài, nghề nuôi mình, cần bảo dưỡng", que: [{n: 48}],
 viSao: "Quẻ Tỉnh là nước trên gỗ: gàu múc nước lên nuôi người. Lời quẻ nói đổi làng không đổi giếng: giếng không mất không được, ai cũng dùng. Nhưng dây chưa tới nước hoặc vỡ bình thì xấu. Đại tượng dạy khích lệ dân chăm làm, giúp nhau. Giếng phải vét, phải xây mới trong.",
 trich: {n: 48, zh: "改邑不改井，无喪无得", hv: "Cải ấp bất cải tỉnh, vô táng vô đắc.", dich: "Đổi làng mà không đổi giếng; giếng không mất không được, cứ nuôi người."},
 ungXu: {nen: ["Mỗi năm dành thời gian và tiền sửa chính cái nghề đang nuôi mình.", "Làm việc nào cũng đến nơi: múc lên tới miệng giếng mới thôi.", "Giữ nguồn chung cho nhiều người dùng được, không chỉ mình."],
  tranh: ["Bỏ nghề cũ chạy theo món mới chưa có giếng.", "Làm nửa chừng rồi đổ cho giếng cạn."]},
 canhBao: {y: "Nếu giếng bỏ hoang lâu, nguồn cạn dần, đọc", ma: "lk3"}},
{ma: "tb6", nhom: "tb", ten: "Muốn chia lợi, trả công, thưởng cho người làm cùng", que: [{n: 42, hao: 5}, {n: 43}],
 viSao: "Quẻ Ích là gió và sấm: bớt trên thêm dưới, dân vui không cùng. Thoán nói trên xuống dưới, đạo ấy sáng lớn. Hào năm có lòng thành muốn ban ơn thì không cần hỏi cũng rất tốt, và dân cũng mến đức mình. Đại tượng quẻ Quải dạy ban lộc xuống dưới, giữ khư khư là điều kiêng.",
 trich: {n: 42, hao: 5, zh: "有孚惠心，勿問元吉", hv: "Hữu phu huệ tâm, vật vấn nguyên cát.", dich: "Có lòng thành muốn làm ơn, không cần hỏi cũng rất tốt."},
 ungXu: {nen: ["Chia theo công rõ ràng, công khai cách tính.", "Chia sớm và đều hơn là chia to một lần.", "Giữ phần cho việc chung và dự phòng, nói trước với mọi người."],
  tranh: ["Chia theo cảm tình.", "Hứa thưởng rồi lùi."]},
 canhBao: {y: "Nếu chia mà người ta không đáp lại, lòng mình bắt đầu lung lay, đọc", ma: "ht4"}},

// ===== Gia đình =====
{ma: "gi1", nhom: "gi", ten: "Nhà cửa lộn xộn, ai cũng làm theo ý mình", que: [{n: 37, hao: 3}],
 viSao: "Quẻ Gia Nhân là gió từ lửa ra: trong có nếp thì ngoài có khí. Thoán nói cha ra cha, con ra con, mỗi người đúng chỗ thì nhà chính. Đại tượng dạy nói có thực, làm có thường. Hào ba: nghiêm quá nhà kêu ca mà vẫn tốt; buông quá cười đùa thì cuối cùng tiếc.",
 trich: {n: 37, hao: 3, zh: "家人嗃嗃，悔厲吉；婦子嘻嘻，終吝", hv: "Gia nhân hạc hạc, hối lệ cát; phụ tử hi hi, chung lận.", dich: "Nhà nghiêm quá có tiếng kêu ca, tuy nguy mà tốt; nhà cười đùa buông thả thì cuối cùng đáng tiếc."},
 ungXu: {nen: ["Đặt ba nếp chung không ai được phá: giờ cơm, tiền chung, việc nhà.", "Người lớn làm trước, nói sau.", "Mỗi tuần một bữa cả nhà ngồi, nói việc nhà, không nói việc ngoài."],
  tranh: ["Mỗi người một luật, con cái theo người dễ hơn.", "Dùng tiền thay cho nếp."]},
 canhBao: {y: "Nếu vợ chồng đã bất hòa, đọc", ma: "gi4"}},
{ma: "gi2", nhom: "gi", ten: "Dạy con: nên nghiêm hay nên chiều", que: [{n: 4, hao: 2}],
 viSao: "Quẻ Mông là suối dưới núi: trẻ nhỏ cần khai sáng. Hào đầu bảo lúc mới tối phải dùng kỷ luật để cởi trói cho sự tối. Hào hai lại bao dung kẻ tối, nên tốt, con gánh được việc nhà. Hai hào đi cùng: nghiêm để mở, dung để nuôi. Đại tượng dạy quả quyết mà nuôi đức.",
 trich: {n: 4, hao: 2, zh: "包蒙吉，納婦吉，子克家", hv: "Bao mông cát, nạp phụ cát, tử khắc gia.", dich: "Bao dung người còn tối, tốt; con sẽ gánh được việc nhà."},
 ungXu: {nen: ["Ít luật, luật nào đã đặt thì giữ đến cùng.", "Phạt việc, không phạt người; phạt xong là xong.", "Giao con một việc thật trong nhà và chịu kết quả của việc ấy."],
  tranh: ["Lúc nghiêm lúc chiều tùy tâm trạng mình.", "Dạy bằng so sánh với con nhà khác."]},
 canhBao: {y: "Khi con đã lớn, muốn tự chọn đường, hãy để con tự tìm thầy; đọc", ma: "ks3"}},
{ma: "gi3", nhom: "gi", ten: "Cha mẹ để lại việc hỏng, nợ nần; con phải sửa", que: [{n: 18, hao: 1}],
 viSao: "Quẻ Cổ là gió dưới núi: gió bị núi chặn, lâu ngày sinh mục. Thoán nói Cổ là rối rồi lại sửa được. Hào đầu sửa việc hỏng của cha: có con như thế thì cha không lỗi, dù nguy mà cuối tốt. Hào hai sửa việc của mẹ thì không thể cứng. Đại tượng dạy chấn hưng, nuôi đức.",
 trich: {n: 18, hao: 1, zh: "幹父之蠱，有子考，无咎，厲終吉", hv: "Cán phụ chi cổ, hữu tử khảo, vô cữu, lệ chung cát.", dich: "Sửa việc hỏng của cha, có con như thế thì cha không lỗi; nguy nhưng cuối cùng tốt."},
 ungXu: {nen: ["Kê hết: nợ ai, bao nhiêu, giấy tờ gì; không giấu nhau trong nhà.", "Sửa việc, không trách người; cha mẹ có thời của họ.", "Với mẹ, với người yếu, sửa mềm: nói riêng, làm dần."],
  tranh: ["Dung túng để yên chuyện; để lâu mục thêm.", "Gánh một mình không cho anh em biết."]},
 canhBao: {y: "Nếu nợ quá lớn vượt sức, cách bớt ở mục", ma: "tb2"}},
{ma: "gi4", nhom: "gi", ten: "Vợ chồng xích mích, trợn mắt nhìn nhau", que: [{n: 9, hao: 3}, {n: 38}],
 viSao: "Hào ba quẻ Tiểu Súc là xe tuột nan bánh, vợ chồng trợn mắt. Tiểu tượng nói không giữ được nhà. Trong quẻ, một hào âm nhỏ kìm được hào dương: chuyện nhỏ cản được cả nhà. Quẻ Khuê dạy khi hai bên quay lưng thì làm việc nhỏ trước, giữ chỗ chung.",
 trich: {n: 9, hao: 3, zh: "車說輹，夫妻反目", hv: "Dư thoát phúc, phu thê phản mục.", dich: "Xe tuột nan bánh, vợ chồng trợn mắt nhìn nhau."},
 ungXu: {nen: ["Tìm cái nan bánh: thường là một việc nhỏ lặp lại, không phải việc lớn.", "Nói việc, không nói người: 'việc này' thay cho 'anh luôn thế'.", "Làm chung một việc nhỏ mỗi ngày: nấu, đi bộ, đón con."],
  tranh: ["Kéo cha mẹ hai bên vào.", "Im lặng nhiều ngày coi như trừng phạt."]},
 canhBao: {y: "Nếu đã tính chuyện chia tay, cân nhắc lui hay cố ở mục", ma: "lk1"}},
{ma: "gi5", nhom: "gi", ten: "Tính chuyện cưới hỏi: đúng lúc hay vội", que: [{n: 53}, {n: 54}],
 viSao: "Hai quẻ liền nhau cùng nói chuyện con gái về nhà chồng. Tiệm là chim hồng bay từng chặng, về nhà chồng đúng lễ thì tốt. Quy Muội là em gái vội theo, vị không đúng, tình lấn lễ: đi thì xấu. Đại tượng Quy Muội dạy giữ trọn lâu dài và biết trước chỗ hỏng.",
 trich: {n: 54, zh: "征凶，无攸利", hv: "Chinh hung, vô du lợi.", dich: "Vội vàng đi tới thì xấu, không có lợi gì."},
 ungXu: {nen: ["Hỏi mình ba điều: biết người ấy đủ chưa, hai nhà đã gặp chưa, tiền sống chung tính chưa.", "Đi đúng chặng: ra mắt, hỏi, cưới; không bỏ chặng vì vội.", "Nhìn kết cục: mười năm sau mình muốn nhà thế nào."],
  tranh: ["Cưới vì có thai, vì tuổi, vì người ta hối.", "Vị thế lệch quá mà không nói rõ với nhau."]},
 canhBao: {y: "Khi đã thành nhà, nếp nhà ở mục", ma: "gi1"}},
{ma: "gi6", nhom: "gi", ten: "Nuôi người thân, lo ăn uống, sức khỏe cả nhà", que: [{n: 27}],
 viSao: "Quẻ Di là sấm dưới núi: cái hàm trên dừng, hàm dưới động, là nuôi. Lời quẻ nói xem cách người ta nuôi và cách tự kiếm miếng ăn. Thoán nói nuôi đúng người thì tốt. Đại tượng dạy cẩn thận lời nói, tiết độ ăn uống: cái vào miệng và cái ra miệng.",
 trich: {n: 27, zh: "觀頤，自求口實", hv: "Quan di, tự cầu khẩu thực.", dich: "Xem cách nuôi dưỡng, và tự tìm miếng ăn cho mình."},
 ungXu: {nen: ["Nguồn nuôi phải chính đáng và đều; không nuôi nhà bằng tiền may rủi.", "Ăn uống có giờ, có mức; người lớn làm gương trước.", "Lời nói trong nhà cũng là nuôi: ít lời cay, nhiều lời đúng."],
  tranh: ["Ỷ vào người khác nuôi.", "Ghen với nhà người ta ăn gì, có gì."]},
 canhBao: {y: "Nếu phải nuôi mà sức mình đã cạn, cách tiết chế ở mục", ma: "tb1"}},

// ===== Lãnh đạo và tổ chức =====
{ma: "ld1", nhom: "ld", ten: "Đang thuận, trên dưới một lòng; làm gì để giữ", que: [{n: 11, hao: 3}],
 viSao: "Quẻ Thái là trời đất giao nhau: khí dưới lên, khí trên xuống, thông. Lời quẻ nói cái nhỏ đi, cái lớn đến. Nhưng hào ba đứng giữa quẻ nhắc: không bằng nào không nghiêng, không đi nào không về. Đại tượng dạy người trên điều hòa cho hợp lẽ trời đất mà đỡ dân.",
 trich: {n: 11, hao: 3, zh: "无平不陂，无往不復，艱貞无咎", hv: "Vô bình bất bí, vô vãng bất phục, gian trinh vô cữu.", dich: "Không chỗ bằng nào không nghiêng, không đi nào không trở lại; trong gian nan giữ chính thì không lỗi."},
 ungXu: {nen: ["Lúc thuận, sửa cái nền: quy trình, sổ sách, người kế cận.", "Để dành một phần lợi cho lúc khó; nói rõ với mọi người vì sao.", "Bao dung cả người thô, người xa; không kéo bè."],
  tranh: ["Mở rộng theo đà mà quên cái nền.", "Tin rằng thuận là do mình giỏi."]},
 canhBao: {y: "Khi thấy tường thành đổ xuống hào, thế bắt đầu suy, đọc", ma: "lk3"}},
{ma: "ld2", nhom: "ld", ten: "Người dưới làm sai, có nên phạt", que: [{n: 21, hao: 1}, {n: 40}],
 viSao: "Quẻ Phệ Hạp dạy xử kẻ ngăn trở bằng hình phạt sáng rõ. Hào đầu đeo cùm chân, mất ngón chân mà không lỗi: phạt nhẹ sớm để răn, khỏi phạt nặng về sau. Hệ từ bình hào này: răn nhỏ mà răn được lớn là phúc của kẻ nhỏ. Đại tượng quẻ Giải lại dạy tha lỗi lầm, giảm tội.",
 trich: {n: 21, hao: 1, zh: "屨校滅趾，无咎", hv: "Lũ giảo diệt chỉ, vô cữu.", dich: "Đeo cùm ở chân, mất ngón chân; không lỗi."},
 ungXu: {nen: ["Phân biệt lỡ và cố: lỡ thì tha và dạy, cố thì phạt.", "Phạt sớm, nhẹ, rõ lý; phạt xong không nhắc lại.", "Xem lại mình: việc giao có rõ không, có quá sức họ không."],
  tranh: ["Để dồn rồi phạt một lần thật nặng.", "Phạt trước mặt mọi người để dằn mặt."]},
 canhBao: {y: "Nếu người ấy cố tình, lặp lại nhiều lần, đọc", ma: "tc2"}},
{ma: "ld3", nhom: "ld", ten: "Phải huy động nhiều người làm việc lớn, ai cầm đầu", que: [{n: 7, hao: 1}],
 viSao: "Quẻ Sư là nước trong đất: dân là quân, chứa trong đất. Lời quẻ nói phải chính đáng và có người già dặn cầm quân thì tốt. Hào đầu: ra quân phải có kỷ luật, không thì xấu. Hào năm dặn con trưởng cầm quân, kẻ em xen vào thì chở xác về. Đại tượng dạy bao dung dân, nuôi quần chúng.",
 trich: {n: 7, hao: 1, zh: "師出以律，否臧，凶", hv: "Sư xuất dĩ luật, phủ tang, hung.", dich: "Ra quân phải theo kỷ luật; không giữ được kỷ luật thì xấu."},
 ungXu: {nen: ["Một người quyết, nói rõ từ đầu; người khác góp ý rồi theo.", "Luật trước người: ai cũng theo cùng một luật, kể cả người cầm đầu.", "Mục tiêu phải chính đáng và nói được ra miệng với mọi người."],
  tranh: ["Hai ba người cùng chỉ huy.", "Thưởng người thân, phạt người lạ."]},
 canhBao: {y: "Khi việc lớn xong, cần ổn định và đặt người đúng chỗ, đọc", ma: "ld6"}},
{ma: "ld4", nhom: "ld", ten: "Mình ở sát người đứng đầu, vị trí nhạy cảm", que: [{n: 2, hao: 4}, {n: 1, hao: 4}],
 viSao: "Hào bốn là chỗ sát ngôi tôn. Hệ từ nói hào hai được khen nhiều, hào bốn lo sợ nhiều, vì gần người trên. Hào bốn quẻ Khôn thắt miệng túi: không lỗi, cũng không được khen. Hào bốn quẻ Càn hoặc nhảy hoặc còn ở vực: tiến lui tùy thời, không vì ý riêng.",
 trich: {n: 2, hao: 4, zh: "括囊，无咎无譽", hv: "Quát nang, vô cữu vô dự.", dich: "Thắt miệng túi lại: không lỗi, cũng không được khen."},
 ungXu: {nen: ["Nói ít, nhất là chuyện của người trên; không mang chuyện trên xuống dưới.", "Làm việc đúng phần mình, báo đủ, không tranh công.", "Giữ quan hệ với người dưới; sát trên mà xa dưới là mất gốc."],
  tranh: ["Cậy gần người trên mà lấn người ngang hàng.", "Nhận quà, nhận lời nhờ vì mình ở gần."]},
 canhBao: {y: "Khi có công, được khen nhiều, cách giữ ở mục", ma: "ld7"}},
{ma: "ld5", nhom: "ld", ten: "Đến lúc phải thay đổi lớn, cải tổ", que: [{n: 49}, {n: 50}],
 viSao: "Quẻ Cách là lửa trong đầm: nước lửa khắc nhau thì phải đổi. Lời quẻ nói đến ngày mới được tin, rồi rất thông. Thoán nói trời đất đổi mà bốn mùa thành; đổi đúng thời thì hối mất. Hào ba dặn lời bàn đổi phải qua ba lần xét. Quẻ Đỉnh liền sau: đổi rồi phải nấu cho chín.",
 trich: {n: 49, zh: "已日乃孚", hv: "Dĩ nhật nãi phu.", dich: "Đến đúng ngày, việc đổi mới được người tin."},
 ungXu: {nen: ["Nói vì sao phải đổi trước khi nói đổi thế nào.", "Bàn ba lần với ba nhóm người khác nhau, rồi mới quyết.", "Đổi một lần cho trọn; đổi nửa vời tốn hơn không đổi."],
  tranh: ["Đổi vì mới lên, muốn khác người trước.", "Đổi tên gọi, giữ nguyên cách làm."]},
 canhBao: {y: "Đổi xong, việc kế là ổn định và đặt người; đọc", ma: "ld6"}},
{ma: "ld6", nhom: "ld", ten: "Sau thay đổi, cần ổn định; đặt ai vào việc nào", que: [{n: 50, hao: 4}],
 viSao: "Quẻ Đỉnh là lửa trên gỗ: cái vạc nấu chín, nuôi người hiền. Đại tượng dạy ngôi ngay ngắn, mệnh vững. Hào bốn vạc gãy chân, đổ cháo của vua: giao việc cho người không kham được. Hệ từ bình hào này: đức mỏng mà ngôi cao, sức nhỏ mà gánh nặng, ít khi không gặp họa.",
 trich: {n: 50, hao: 4, zh: "鼎折足，覆公餗，其刑渥，凶", hv: "Đỉnh chiết túc, phúc công tốc, kỳ hình ốc, hung.", dich: "Vạc gãy chân, đổ cháo của vua, thân mình nhơ nhuốc; xấu."},
 ungXu: {nen: ["Đặt người theo sức thật đã thấy, không theo lời hứa hay thân quen.", "Việc nặng chia hai người gánh, có người dự bị.", "Ba tháng đầu xem lại từng vị trí một lần."],
  tranh: ["Cất nhắc nhanh người vừa giúp mình đổi.", "Giữ người cũ ở chỗ cũ chỉ vì ngại."]},
 canhBao: {y: "Khi đã vững, trên dưới thuận, cách giữ ở mục", ma: "ld1"}},
{ma: "ld7", nhom: "ld", ten: "Có công lớn, được khen; muốn giữ được lâu", que: [{n: 15, hao: 3}],
 viSao: "Quẻ Khiêm là núi trong đất: cao mà ở dưới. Lời quẻ nói người quân tử khiêm thì có kết quả đến cuối. Hào ba có công mà khiêm: kết quả trọn, tốt. Hệ từ bình: có công mà không kể, đó là hậu đến cùng. Đại tượng dạy bớt chỗ nhiều, bù chỗ ít.",
 trich: {n: 15, hao: 3, zh: "勞謙君子，有終吉", hv: "Lao khiêm quân tử, hữu chung cát.", dich: "Người quân tử có công mà khiêm, kết quả trọn vẹn, tốt."},
 ungXu: {nen: ["Khi được khen, kể tên người đã làm cùng trước khi kể việc.", "Chia phần thưởng; giữ phần nhỏ hơn phần mình đáng được.", "Nhận việc khó kế tiếp thay cho nhận chức."],
  tranh: ["Nhắc công cũ khi bị góp ý.", "Để người ta khen mãi mà không nói lời cảm ơn người dưới."]},
 canhBao: {y: "Nếu khen nhiều mà mình bắt đầu tin mình hơn người, đọc", ma: "lk8"}},
{ma: "ld8", nhom: "ld", ten: "Tổ chức rã đám, lòng người tan", que: [{n: 59, hao: 4}, {n: 45}],
 viSao: "Quẻ Hoán là gió trên nước: thổi tan. Thoán nói vua đến nhà tông miếu để tụ lòng người lại. Hào bốn làm tan bè phái thì rất tốt, tan rồi lại tụ thành gò lớn. Đại tượng dạy tế Thượng đế, lập miếu: dựng một điều chung để người ta quay về. Quẻ Tụy nói cách tụ.",
 trich: {n: 59, hao: 4, zh: "渙其群，元吉", hv: "Hoán kỳ quần, nguyên cát.", dich: "Làm tan bè phái nhỏ, rất tốt; tan rồi mới tụ lại được thành lớn."},
 ungXu: {nen: ["Gọi tên một mục đích chung lớn hơn mọi phe, nói cho mọi người nghe.", "Giải tán nhóm nhỏ của chính mình trước.", "Gặp từng người đã rời, hỏi vì sao; không giữ, chỉ nghe."],
  tranh: ["Dùng tiền giữ người.", "Trừng phạt người đi."]},
 canhBao: {y: "Khi đã quy tụ lại, cách giữ thuận ở mục", ma: "ld1"}},

// ===== Lui, kết thúc, mất mát =====
{ma: "lk1", nhom: "lk", ten: "Nên rút lui hay cố thêm", que: [{n: 33, hao: 5}, {n: 34, hao: 6}],
 viSao: "Quẻ Độn là núi dưới trời: trời cao lánh núi, lui mà không mất. Thoán nói lui đúng thời là thông. Hào năm lui một cách đẹp, giữ chính thì tốt: lui lúc còn được chọn cách lui. Hào trên quẻ Đại Tráng là dê húc rào, không lùi không tiến được: cố quá thì mất cả hai đường.",
 trich: {n: 33, hao: 5, zh: "嘉遯，貞吉", hv: "Gia độn, trinh cát.", dich: "Lui một cách đẹp; giữ chính thì tốt."},
 ungXu: {nen: ["Hỏi ba câu: còn sức không, còn thời không, còn người không; hai câu không thì lui.", "Lui lúc còn chọn được cách lui: còn tiền, còn tiếng, còn bạn.", "Nói rõ với người liên quan vì sao lui, lui đến đâu."],
  tranh: ["Cố vì đã bỏ quá nhiều.", "Bỏ ngang không báo ai."]},
 canhBao: {y: "Nếu muốn lui mà bị vướng, đọc", ma: "lk2"}},
{ma: "lk2", nhom: "lk", ten: "Muốn rút mà vướng: hợp đồng, người thân, nợ", que: [{n: 34, hao: 6}, {n: 33, hao: 3}],
 viSao: "Hào trên quẻ Đại Tráng là dê húc rào, mắc sừng: không lùi được, không tiến được. Nhưng lời hào nói biết gian nan thì tốt. Hào ba quẻ Độn muốn lui mà bị buộc, có nguy; nên lo cho người quanh mình trước. Vướng không phải ngõ cụt, chỉ là phải gỡ chậm.",
 trich: {n: 34, hao: 6, zh: "羝羊觸藩，不能退，不能遂", hv: "Đê dương xúc phiên, bất năng thoái, bất năng toại.", dich: "Dê đực húc rào mắc sừng, không lùi được, không tiến được."},
 ungXu: {nen: ["Kê rõ từng cái vướng: giấy nào, người nào, khoản nào, hạn nào.", "Gỡ cái dễ nhất trước; mỗi cái gỡ được là sừng nhẹ đi.", "Chịu mất một phần để gỡ: phạt hợp đồng, bớt lời, xin lỗi."],
  tranh: ["Giật mạnh một lần: cắt đứt, trốn nợ, bỏ người.", "Để nguyên cho thời gian lo."]},
 canhBao: {y: "Khi đã gỡ được ràng buộc, cách dọn dẹp ở mục", ma: "tc4"}},
{ma: "lk3", nhom: "lk", ten: "Thế đang suy, bị bào mòn dần", que: [{n: 23, hao: 6}, {n: 24}],
 viSao: "Quẻ Bác là núi tựa trên đất: năm hào âm bóc dần một hào dương. Lời quẻ nói không lợi đi đâu. Thoán nói quân tử coi trọng đầy vơi tiêu tức, đó là đường trời. Hào trên quả lớn không bị ăn: giữ hạt giống thì mùa sau lại có. Quẻ Phục liền sau là dương quay về.",
 trich: {n: 23, hao: 6, zh: "碩果不食，君子德車，小人剝廬", hv: "Thạc quả bất thực, quân tử đắc dư, tiểu nhân bác lư.", dich: "Quả lớn còn lại không bị ăn; người quân tử giữ được xe, kẻ nhỏ phá nát nhà mình."},
 ungXu: {nen: ["Chọn cái cốt lõi phải giữ bằng mọi giá: nghề, người, uy tín; bỏ phần còn lại.", "Thu về, không mở; vun cho người dưới để còn chỗ đứng.", "Chờ; Bác đến cùng thì Phục."],
  tranh: ["Chống đỡ khắp nơi, mất luôn hạt giống.", "Đổ lỗi cho người dưới khi thế suy."]},
 canhBao: {y: "Khi mầm mới đã nhú, bắt đầu lại ở mục", ma: "ks6"}},
{ma: "lk4", nhom: "lk", ten: "Việc đã xong, thành công rồi; làm gì tiếp", que: [{n: 63}, {n: 64}],
 viSao: "Quẻ Ký Tế là nước trên lửa: mọi hào đều đúng chỗ, việc đã thành. Lời quẻ nói lúc đầu tốt, cuối cùng loạn. Thoán nói đến cùng thì dừng, đạo nghèo. Đại tượng dạy nghĩ đến họa mà phòng trước. Quẻ Vị Tế đứng cuối sách: không việc gì xong hẳn.",
 trich: {n: 63, zh: "初吉終亂", hv: "Sơ cát chung loạn.", dich: "Lúc đầu tốt, cuối cùng rối loạn, nếu không phòng."},
 ungXu: {nen: ["Viết lại cách đã làm thành quy trình, trước khi quên.", "Kiểm rủi ro ngay lúc yên: cái gì sẽ hỏng trước, ai sẽ đi.", "Nghỉ một nhịp rồi mới mở việc mới; không mở ngay vì đang hứng."],
  tranh: ["Nói với mình: xong rồi, không cần xem lại.", "Mở việc lớn gấp đôi ngay sau thành công."]},
 canhBao: {y: "Nếu nhận ra việc thực ra còn dở, chưa qua sông, đọc", ma: "lk9"}},
{ma: "lk5", nhom: "lk", ten: "Mất tiền, mất của", que: [{n: 51, hao: 2}, {n: 38, hao: 1}],
 viSao: "Hào hai quẻ Chấn: sấm đến, liệu chừng mất của, leo lên gò cao, chớ đuổi theo, bảy ngày sẽ được lại. Tiểu tượng nói ở giữa nên không hoảng. Hào đầu quẻ Khuê cũng dặn mất ngựa chớ đuổi, nó tự về. Người xưa dạy mất của thì giữ người, đừng đuổi theo của.",
 trich: {n: 51, hao: 2, zh: "億喪貝，躋于九陵，勿逐，七日得", hv: "Ức táng bối, tê vu cửu lăng, vật trục, thất nhật đắc.", dich: "Liệu chừng mất của; lên chỗ cao mà đứng, chớ đuổi theo, bảy ngày sẽ được lại."},
 ungXu: {nen: ["Giữ người trước: sức khỏe, gia đình, uy tín; của mất là của.", "Ghi lại vì sao mất; bài học là thứ còn lại.", "Không gỡ ngay bằng cách liều; kiếm lại từ nghề đang có."],
  tranh: ["Đuổi theo của bằng cách vay thêm, chơi thêm.", "Giấu người nhà."]},
 canhBao: {y: "Nếu mất của vì người khác lừa, cân nhắc kiện ở mục", ma: "tc1"}},
{ma: "lk6", nhom: "lk", ten: "Mất người thân, có tang", que: [{n: 30, hao: 5}, {n: 62}],
 viSao: "Hào năm quẻ Ly: nước mắt tuôn rơi, lo buồn than thở, mà tốt. Tiểu tượng nói vì ở ngôi tôn mà biết lo. Khóc được là giữ được sáng. Đại tượng quẻ Tiểu Quá dạy việc tang hơi quá về thương xót là đúng mức. Hào ba quẻ Ly nói mặt trời xế mà không hát được thì già mà than.",
 trich: {n: 30, hao: 5, zh: "出涕沱若，戚嗟若，吉", hv: "Xuất thế đà nhược, thích ta nhược, cát.", dich: "Nước mắt tuôn rơi, lo buồn than thở; như thế là tốt."},
 ungXu: {nen: ["Cho phép mình khóc, nghỉ, chậm; không tỏ ra vững khi chưa vững.", "Lo việc tang đúng lễ, vừa sức nhà; thương xót là lễ, không phải tiền.", "Giữ một việc nhỏ của người đã mất mà làm tiếp."],
  tranh: ["Quyết chuyện nhà, chuyện tiền trong trăm ngày đầu.", "Trách người thân khác đã không làm đủ."]},
 canhBao: {y: "Khi hết tang, cần sắp lại nếp nhà, đọc", ma: "gi1"}},
{ma: "lk7", nhom: "lk", ten: "Đi xa, rời quê, chuyển chỗ làm, nơi ở", que: [{n: 56}],
 viSao: "Quẻ Lữ là lửa trên núi: lửa cháy lan, không ở lâu một chỗ. Lời quẻ nói thông nhỏ; người đi xa giữ chính thì tốt. Hào hai đến được quán trọ, giữ được tiền và người giúp trung thành. Đại tượng dạy sáng và cẩn thận khi xử việc, không giam án lâu. Người lạ chỗ lạ, lấy khiêm làm nhà.",
 trich: {n: 56, zh: "小亨，旅貞吉", hv: "Tiểu hanh, lữ trinh cát.", dich: "Thông ở việc nhỏ; người đi xa giữ chính thì tốt."},
 ungXu: {nen: ["Giữ chặt tiền và giấy tờ; chỗ lạ dễ mất.", "Tử tế với người giúp mình nơi mới, dù là người nhỏ.", "Việc nhỏ làm đều để có tiếng; chưa đặt cược lớn nơi chưa quen."],
  tranh: ["Cậy gốc gác cũ nơi người ta không biết mình.", "Cười trước, lo sau: coi thường chỗ ở tạm."]},
 canhBao: {y: "Khi đã có chỗ đứng nơi mới, cách tiến từng bước ở mục", ma: "ks5"}},
{ma: "lk8", nhom: "lk", ten: "Đã ở đỉnh cao, biết sắp xế", que: [{n: 1, hao: 6}, {n: 55}],
 viSao: "Hào trên quẻ Càn là rồng bay quá cao, có hối. Tiểu tượng nói đầy thì không lâu. Văn ngôn nói cao mà không có dân, hiền ở dưới mà không giúp. Thoán quẻ Phong nói mặt trời giữa trưa thì xế, trăng đầy thì khuyết. Biết sắp xế thì đỉnh thành chỗ hạ cánh, không thành chỗ rơi.",
 trich: {n: 1, hao: 6, zh: "亢龍，有悔", hv: "Kháng long, hữu hối.", dich: "Rồng bay lên quá cao, có hối hận."},
 ungXu: {nen: ["Chủ động giảm: bớt vai, trao việc, chọn người kế.", "Dùng ánh sáng còn lại soi cho người khác: dạy, viết, nâng người trẻ.", "Giữ một việc tay chân, một người nói thẳng với mình."],
  tranh: ["Thêm chức, thêm việc để chứng tỏ còn đỉnh.", "Chỉ nghe người khen."]},
 canhBao: {y: "Khi thấy mình đã quá đà, lui thế nào ở mục", ma: "lk1"}},
{ma: "lk9", nhom: "lk", ten: "Việc dang dở, chưa đến đích, muốn bỏ", que: [{n: 64}],
 viSao: "Quẻ Vị Tế là lửa trên nước: mọi hào chưa đúng chỗ, việc chưa thành. Lời quẻ kể con cáo nhỏ gần qua sông thì ướt đuôi, không lợi gì. Thoán nói chưa ra khỏi giữa dòng. Đại tượng dạy thận trọng phân biệt, đặt mỗi thứ đúng chỗ. Sách Dịch kết bằng quẻ này: việc chưa xong là lẽ thường.",
 trich: {n: 64, zh: "小狐汔濟，濡其尾，无攸利", hv: "Tiểu hồ ngật tế, nhu kỳ vĩ, vô du lợi.", dich: "Con cáo nhỏ gần qua được sông thì ướt đuôi; không có lợi gì."},
 ungXu: {nen: ["Đếm lại: còn bao nhiêu phần, cần bao lâu, thiếu gì; đừng đoán.", "Sắp lại người và việc cho đúng chỗ rồi mới đi tiếp.", "Giữ sức cho đoạn cuối; đuôi ướt vì mệt lúc gần bờ."],
  tranh: ["Tuyên bố xong khi chưa xong.", "Bỏ vì chán, không vì đã xét."]},
 canhBao: {y: "Khi qua được sông, việc xong rồi, đọc", ma: "lk4"}}
]};
